css:
.sl-testimonial-split {
    padding: clamp(3rem, 6vw, 6rem) clamp(1rem, 4vw, 2rem);
    width: 100%;
    background-color: var(--smartlearn-bg);
    font-family: var(--smartlearn-body-font, system-ui, sans-serif);
}

.sl-testimonial-split .sl-container {
    max-width: 1200px;
    margin: 0 auto;
}

.sl-testimonial-split .sl-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 4rem;
    align-items: center;
}

@media (max-width: 900px) {
    .sl-testimonial-split .sl-grid {
        grid-template-columns: 1fr;
        gap: 2.5rem;
    }
}

.sl-testimonial-split .sl-image-wrapper {
    position: relative;
    width: 100%;
}

.sl-testimonial-split .sl-img-frame {
    width: 100%;
    aspect-ratio: 4 / 5;
    border-radius: var(--smartlearn-radius, 16px);
    overflow: hidden;
}

@media (max-width: 900px) {
    .sl-testimonial-split .sl-img-frame {
        aspect-ratio: 16 / 10;
    }
}

.sl-testimonial-split .sl-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    object-position: center top;
}

.sl-testimonial-split .sl-floating-badge {
    position: absolute;
    bottom: 2rem;
    inset-inline-end: -1rem;
    background: var(--smartlearn-card-bg);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--smartlearn-card-border, rgba(0, 0, 0, 0.1));
    padding: 1.5rem;
    border-radius: var(--smartlearn-radius, 12px);
    text-align: center;
    box-shadow: 0 20px 40px rgba(0, 0, 0, 0.2);
}

@media (max-width: 600px) {
    .sl-testimonial-split .sl-floating-badge {
        bottom: 1rem;
        inset-inline-end: 1rem;
        padding: 1rem 1.25rem;
    }
}

.sl-testimonial-split .sl-badge-num {
    font-size: 2rem;
    font-weight: 800;
    color: var(--smartlearn-primary);
}

.sl-testimonial-split .sl-badge-text {
    font-size: 0.875rem;
    color: var(--smartlearn-text);
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 600;
}

.sl-testimonial-split .sl-title {
    font-family: var(--smartlearn-heading-font, system-ui, sans-serif);
    font-size: clamp(1.875rem, 4vw, 3rem);
    font-weight: 800;
    color: var(--smartlearn-text);
    line-height: 1.15;
    margin-bottom: 2rem;
}

.sl-testimonial-split .sl-quote-figure,
.sl-testimonial-split .sl-blockquote {
    margin: 0;
}

.sl-testimonial-split .sl-quote {
    font-size: clamp(1.0625rem, 2vw, 1.25rem);
    color: var(--smartlearn-text-muted);
    line-height: 1.8;
    margin-bottom: 3rem;
    position: relative;
}

.sl-testimonial-split .sl-author {
    border-inline-start: 3px solid var(--smartlearn-primary);
    padding-inline-start: 1.5rem;
}

.sl-testimonial-split .sl-name {
    font-weight: 700;
    color: var(--smartlearn-text);
    font-size: 1.125rem;
}

.sl-testimonial-split .sl-role {
    color: var(--smartlearn-text-muted);
    font-size: 0.875rem;
}
